@export var speed: float = 300.0
@export var jump_velocity: float = -400.0

var gravity: float = ProjectSettings.get_setting("physics/2d/default_gravity")

func _physics_process(delta: float) -> void:
    # 1. Применяем гравитацию, если персонаж в воздухе
    if not is_on_floor():
        velocity.y += gravity * delta

    # 2. Обработка прыжка
    if Input.is_action_just_pressed("ui_accept") and is_on_floor():
        velocity.y = jump_velocity

    # 3. Горизонтальное движение
    var direction: float = Input.get_axis("ui_left", "ui_right")
    if direction != 0.0:
        velocity.x = direction * speed
    else:
        velocity.x = move_toward(velocity.x, 0.0, speed)

    # 4. Вызов физического перемещения без параметров:
    move_and_slide()

if is_on_floor():
    # Персонаж стоит на полу
    pass

if is_on_wall():
    # Персонаж уперся в стену (get_wall_normal() вернет нормаль стены)
    var normal: Vector2 = get_wall_normal()

if is_on_ceiling():
    # Удар головой о потолок
    velocity.y = 0

