class_name InventoryData extends Resource

signal inventory_updated(inv: InventoryData)

@export var slot_datas: Array[SlotData] = []

func add_item(item: ItemData, amount: int = 1) -> bool:
    # 1. Проверяем существующие неполные стаки:
    if item.is_stackable:
        for slot in slot_datas:
            if slot and slot.item == item and slot.quantity < item.max_stack:
                var space_left = item.max_stack - slot.quantity
                var added = mini(space_left, amount)
                slot.quantity += added
                amount -= added
                if amount == 0:
                    inventory_updated.emit(self)
                    return true

    # 2. Ищем первый свободный слот:
    for i in range(slot_datas.size()):
        if slot_datas[i] == null:
            var new_slot = SlotData.new()
            new_slot.item = item
            new_slot.quantity = amount
            slot_datas[i] = new_slot
            inventory_updated.emit(self)
            return true

    return false # Инвентарь полон

