class_name SmartCamera2D extends Camera2D

@export var target: Node2D
@export var follow_speed: float = 8.0
@export var max_offset: Vector2 = Vector2(30, 20)
@export var max_roll: float = 0.1
@export var trauma_decay: float = 1.2

var trauma: float = 0.0
var noise: FastNoiseLite
var noise_y: float = 0.0

func _ready() -> void:
    noise = FastNoiseLite.new()
    noise.seed = randi()
    noise.frequency = 4.0

func _process(delta: float) -> void:
    # 1. Плавное следование за целью:
    if target:
        global_position = global_position.lerp(target.global_position, follow_speed * delta)

    # 2. Расчет затухания тряски:
    if trauma > 0.0:
        trauma = maxf(trauma - trauma_decay * delta, 0.0)
        _apply_shake(delta)

func add_trauma(amount: float) -> void:
    trauma = clampf(trauma + amount, 0.0, 1.0)

func _apply_shake(delta: float) -> void:
    noise_y += delta * 50.0
    var shake_amount: float = trauma * trauma # Квадратичное сглаживание
    rotation = max_roll * shake_amount * noise.get_noise_2d(0, noise_y)
    offset.x = max_offset.x * shake_amount * noise.get_noise_2d(100, noise_y)
    offset.y = max_offset.y * shake_amount * noise.get_noise_2d(200, noise_y)

