extends Node

@export var pool_size: int = 16

var players_pool: Array[AudioStreamPlayer] = []
var music_player: AudioStreamPlayer
var tween_music: Tween

func _ready() -> void:
    for i in range(pool_size):
        var p = AudioStreamPlayer.new()
        p.bus = "SFX"
        add_child(p)
        players_pool.append(p)

    music_player = AudioStreamPlayer.new()
    music_player.bus = "Music"
    add_child(music_player)

func play_sfx(stream: AudioStream, pitch_variance: float = 0.1) -> void:
    for p in players_pool:
        if not p.playing:
            p.stream = stream
            p.pitch_scale = randf_range(1.0 - pitch_variance, 1.0 + pitch_variance)
            p.play()
            return

func play_music(stream: AudioStream, fade_time: float = 1.5) -> void:
    if tween_music and tween_music.is_running():
        tween_music.kill()
    tween_music = create_tween()
    tween_music.tween_property(music_player, "volume_db", -40.0, fade_time)
    tween_music.tween_callback(func():
        music_player.stream = stream
        music_player.play()
    )
    tween_music.tween_property(music_player, "volume_db", 0.0, fade_time)

class_name DialogueBox extends Control

signal dialogue_finished

@onready var name_label: Label = $Panel/NameLabel
@onready var text_label: RichTextLabel = $Panel/TextLabel
@onready var choices_container: VBoxContainer = $Panel/ChoicesContainer

var tween_text: Tween

func show_dialogue_line(speaker: String, text: String, chars_per_sec: float = 35.0) -> void:
    name_label.text = speaker
    text_label.text = text
    text_label.visible_characters = 0
    choices_container.hide()

    var duration: float = float(text.length()) / chars_per_sec
    if tween_text and tween_text.is_running():
        tween_text.kill()
    tween_text = create_tween()
    tween_text.tween_property(text_label, "visible_ratio", 1.0, duration)
    await tween_text.finished

func show_choices(options: Array[String]) -> int:
    # Очищаем предыдущие кнопки
    for child in choices_container.get_children():
        child.queue_free()
    choices_container.show()

    # Ждем нажатия любой кнопки:
    var choice_result: int = -1
    for i in range(options.size()):
        var btn = Button.new()
        btn.text = options[i]
        choices_container.add_child(btn)
        var opt_index = i
        btn.pressed.connect(func():
            choice_result = opt_index
        )

    while choice_result == -1:
        await get_tree().process_frame

    choices_container.hide()
    return choice_result

