@onready var choices_container: VBoxContainer = $Panel/ChoicesContainer

var tween_text: Tween

func show_dialogue_line(speaker: String, text: String, chars_per_sec: float = 35.0) -> void:
    name_label.text = speaker
    text_label.text = text
    text_label.visible_characters = 0
    choices_container.hide()

    var duration = float(text.length()) / chars_per_sec
    if tween_text and tween_text.is_running():
        tween_text.kill()
    tween_text = create_tween()
    tween_text.tween_property(text_label, "visible_ratio", 1.0, duration)
    await tween_text.finished

func show_choices(options: Array[String]) -> int:
    for child in choices_container.get_children():
        child.queue_free()
    choices_container.show()

    var choice_result: int = -1
    for i in range(options.size()):
        var btn = Button.new()
        btn.text = options[i]
        choices_container.add_child(btn)
        var opt_index = i
        btn.pressed.connect(func(): choice_result = opt_index)

    while choice_result == -1:
        await get_tree().process_frame

    choices_container.hide()
    return choice_result

