class_name PlayerController3D extends CharacterBody3D

@export var speed: float = 6.0
@export var acceleration: float = 25.0
@export var jump_velocity: float = 5.0
@export var mouse_sensitivity: float = 0.003
@export var coyote_duration: float = 0.15

var gravity: float = ProjectSettings.get_setting("physics/3d/default_gravity")
var coyote_timer: float = 0.0

@onready var head: Node3D = $Head
@onready var camera: Camera3D = $Head/Camera3D

func _ready() -> void:
    Input.mouse_mode = Input.MOUSE_MODE_CAPTURED

func _unhandled_input(event: InputEvent) -> void:
    if event is InputEventMouseMotion and Input.mouse_mode == Input.MOUSE_MODE_CAPTURED:
        rotate_y(-event.relative.x * mouse_sensitivity)
        head.rotate_x(-event.relative.y * mouse_sensitivity)
        head.rotation.x = clampf(head.rotation.x, -deg_to_rad(85), deg_to_rad(85))

    if event.is_action_pressed("ui_cancel"):
        if Input.mouse_mode == Input.MOUSE_MODE_CAPTURED:
            Input.mouse_mode = Input.MOUSE_MODE_VISIBLE
        else:
            Input.mouse_mode = Input.MOUSE_MODE_CAPTURED

func _physics_process(delta: float) -> void:
    # 1. Гравитация и Coyote Time
    if is_on_floor():
        coyote_timer = coyote_duration
    else:
        coyote_timer -= delta
        velocity.y -= gravity * delta

    # 2. Прыжок с поддержкой Coyote Time
    if Input.is_action_just_pressed("ui_accept") and coyote_timer > 0.0:
        velocity.y = jump_velocity
        coyote_timer = 0.0

    # 3. Направление движения относительно взгляда
    var input_dir: Vector2 = Input.get_vector("ui_left", "ui_right", "ui_up", "ui_down")
    var direction: Vector3 = (transform.basis * Vector3(input_dir.x, 0, input_dir.y)).normalized()

    var target_vel_x = direction.x * speed
    var target_vel_z = direction.z * speed
    velocity.x = move_toward(velocity.x, target_vel_x, acceleration * delta)
    velocity.z = move_toward(velocity.z, target_vel_z, acceleration * delta)

    move_and_slide()

